import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"Argon2 derivation","description":"","frontmatter":{"packageVersion":"0.17.1"},"headers":[],"relativePath":"docs/ARGON2.md","filePath":"docs/ARGON2.md","lastUpdated":1792971609000}`),a={name:`docs/ARGON2.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="argon2-derivation" tabindex="-1">Argon2 derivation <a class="header-anchor" href="#argon2-derivation" aria-label="Permalink to “Argon2 derivation”">​</a></h1><p><code>micro509/kdf</code> derives raw bytes with Argon2d, Argon2i, or Argon2id, versions <code>0x10</code> and <code>0x13</code>. The implementation is TypeScript and works in Node.js, Bun, Deno, browsers, and Cloudflare Workers. It has no WASM binary, native addon, or runtime dependency.</p><p>The default backend tries native WebCrypto for version <code>0x13</code>. When WebCrypto reports that the requested operation is unsupported, the TypeScript core derives the exact requested variant, version, and parameters. Other native failures are returned without retrying. <code>backend: &#39;native&#39;</code> and <code>backend: &#39;portable&#39;</code> select one backend explicitly; callbacks remain supported. The portable backend uses the same Argon2 algorithm in every runtime.</p><p>The TypeScript core implements BLAKE2b, H′, data dependent and data independent address generation, reference block indexing, BlaMka compression, and Argon2&#39;s memory filling and finalization. It follows RFC 9106 §3 and the version 1.2 compatibility behavior used by Argon2 version <code>0x10</code>. The memory matrix is held in a private <code>Uint32Array</code>; its full contents and temporary input blocks are cleared after success or failure. Owned password, salt, secret, and associated data copies are cleared by the public wrapper. As with other JavaScript memory, the runtime may retain inaccessible copies until garbage collection.</p><p>The implementation processes lanes serially and yields to the event loop while filling memory. Parallelism still determines the number of Argon2 lanes and is included unchanged in the derivation. This scheduling does not move the work to another thread or provide cancellation. Resource ceilings apply per call, so applications must also limit concurrent derivations. Requests above the TypeScript backend&#39;s 2 GiB address limit return <code>unsupported</code> before allocation.</p><h2 id="reference-oracle" tabindex="-1">Reference oracle <a class="header-anchor" href="#reference-oracle" aria-label="Permalink to “Reference oracle”">​</a></h2><p>The C/WASM test oracle lives in <code>test/oracles/argon2</code>, with its pinned C sources under <code>vendor/argon2</code> and its compiler plugin in <code>packages/tsdown-plugin-argon2</code>. Run <code>bun build:argon2</code> to rebuild stale artifacts, <code>bun build:argon2 --check</code> to check reproducibility, and <code>bun test:argon2:oracle</code> to compare the TypeScript port against the oracle. This suite covers all three variants and both versions, minimum and unaligned memory sizes, repeated passes, multiple lanes, address-block rollover, long inputs and outputs, optional secret and associated data, and the 64 MiB recommended profile.</p><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to “Evidence”">​</a></h2><p>The governing specification is <a href="https://github.com/kjanat/micro509/blob/v0.17.1/docs/rfc/rfc9106.txt" target="_blank" rel="noreferrer">RFC 9106</a>. Tests compare the implementation with all three RFC 9106 vectors, independent libargon2 vectors for versions <code>0x10</code> and <code>0x13</code>, Node&#39;s independent <code>node:crypto.argon2</code> implementation, and the Bitwarden SDK vector. The tests cover secret and associated data, output lengths above 64 bytes, unaligned memory parameters, input snapshots, resource limits, cooperative scheduling, and temporary-buffer cleanup.</p><p>RFC 9106 recommends Argon2id for general password-based applications. Its second recommended profile uses 64 MiB, three passes, four lanes, a 16-byte salt, and a 32-byte output. Use Argon2d or Argon2i when an existing format requires that exact variant. <code>memoryKiB</code> is passed unchanged into Argon2&#39;s initial hash; the implementation rounds only its internal block allocation as required by the algorithm.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};